import{_ as o,a as t,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第三册：培养技能 · 单元 3 语法总结 · while 与 whereas 的对照至动词后 ing 与 to do 的意义","description":"L41–L60 规则、例句、易错点。","frontmatter":{"title":"第三册：培养技能 · 单元 3 语法总结 · while 与 whereas 的对照至动词后 ing 与 to do 的意义","description":"L41–L60 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-3/unit-03/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 3 语法总结","summary":"L41–L60 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 3 语法总结","link":"/life/english/new-concept/book-3/unit-03/grammar"},"next":{"text":"第三册：培养技能 · 单元 3 语法总结 · 将来完成时的截止视角至时间从句与将来表达整合","link":"/life/english/new-concept/book-3/unit-03/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 3 语法总结","link":"/life/english/new-concept/book-3/unit-03/grammar"},"next":{"text":"第三册：培养技能 · 单元 3 语法总结 · 将来完成时的截止视角至时间从句与将来表达整合","link":"/life/english/new-concept/book-3/unit-03/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/grammar-part-01.md","filePath":"life/english/new-concept/book-3/unit-03/grammar-part-01.md"}'),r={name:"life/english/new-concept/book-3/unit-03/grammar-part-01.md"};function s(i,e,l,h,p,c){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第三册-培养技能-·-单元-3-语法总结-·-while-与-whereas-的对照至动词后-ing-与-to-do-的意义" tabindex="-1">第三册：培养技能 · 单元 3 语法总结 · while 与 whereas 的对照至动词后 ing 与 to do 的意义 <a class="header-anchor" href="#第三册-培养技能-·-单元-3-语法总结-·-while-与-whereas-的对照至动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;第三册：培养技能 · 单元 3 语法总结 · while 与 whereas 的对照至动词后 ing 与 to do 的意义&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-03/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元复习与自测</a></p><h2 id="第三册-培养技能-·-单元-3-语法总结" tabindex="-1">第三册：培养技能 · 单元 3 语法总结 <a class="header-anchor" href="#第三册-培养技能-·-单元-3-语法总结" aria-label="Permalink to &quot;第三册：培养技能 · 单元 3 语法总结 {#第三册-培养技能-·-单元-3-语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-3/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元复习与自测</a></p><h2 id="while-与-whereas-的对照" tabindex="-1">while 与 whereas 的对照 <a class="header-anchor" href="#while-与-whereas-的对照" aria-label="Permalink to &quot;while 与 whereas 的对照 {#while-与-whereas-的对照}&quot;">​</a></h2><p>while 可表示“当……时”的同时背景，也可表示两种事实的对比，具体意义取决于分句是否构成并列差异。whereas 明确表示对照，通常不表示时间。两者都可连接完整分句，主语不必相同。对照不自动等于逻辑矛盾，例如一个地方清静而交通不便是两个维度，而不是互相否定。写比较段落时尽量让两侧使用相同评价标准和相近结构，读者才能看出差别；若需要表达承认条件但仍得出结论，应考虑 although 的让步关系。</p><p><strong>L41 原创例句：</strong> The village is quiet after sunset, whereas the market town remains busy until midnight.</p><p>村庄日落后很安静，而集镇一直忙碌到午夜。</p><p><strong>易错：</strong> while 不能每次都译作“当……时”；While Anna likes silence, Ben enjoys company 中表达的是偏好对照。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">Lesson 41</a></p><h2 id="独立主格的独立主语" tabindex="-1">独立主格的独立主语 <a class="header-anchor" href="#独立主格的独立主语" aria-label="Permalink to &quot;独立主格的独立主语 {#独立主格的独立主语}&quot;">​</a></h2><p>名词或代词加分词等成分可构成独立主格，为主句补充时间、原因或伴随情况，其逻辑主语不同于主句主语。The entrance blocked, we chose another route 中 blocked 与 entrance 构成被动关系。主动进行可用 ing，完成或被动可用过去分词，某些结构也可用形容词或介词短语。它不是完整的限定分句，不能仅用逗号连接两个都有完整谓语的独立句。该形式较书面；信息复杂时改为 because 或 when 从句通常更易理解。</p><p><strong>L42 原创例句：</strong> The main passage blocked, the team returned to the entrance.</p><p>主通道被堵住了，团队便返回入口。</p><p><strong>易错：</strong> The passage was blocked, the team returned 属于逗号拼接两个完整句，需加 so、用分号或改为从句。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-042">Lesson 42</a></p><h2 id="provided-that-与-unless" tabindex="-1">provided that 与 unless <a class="header-anchor" href="#provided-that-与-unless" aria-label="Permalink to &quot;provided that 与 unless {#provided-that-与-unless}&quot;">​</a></h2><p>provided that 或 providing that 表示“只要满足条件”，后接完整分句；unless 通常表示“除非”，相当于 if ... not，但遇到复杂否定、反事实或表达例外时不能机械替换。条件从句谈将来时常用一般现在时，主句才使用 will。unless 本身已含否定条件，通常不再加入 not，除非确实要表达另一层否定。解读条款语言时，必须同时识别条件、结果和例外，语法练习中的虚构规则不能推定为任何现实服务的承诺。</p><p><strong>L43 原创例句：</strong> In this fictional scheme, repairs are covered provided that the damage is reported within a week.</p><p>在这个虚构方案中，只要一周内报告损坏，维修费用就在保障范围内。</p><p><strong>易错：</strong> Unless you don&#39;t report it 会形成额外否定，若意为“如果不报告”，直接写 unless you report it。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">Lesson 43</a></p><h2 id="平行结构与-not-only" tabindex="-1">平行结构与 not only <a class="header-anchor" href="#平行结构与-not-only" aria-label="Permalink to &quot;平行结构与 not only {#平行结构与-not-only}&quot;">​</a></h2><p>and、or、both ... and、not only ... but also 连接的成分应尽量保持相同语法层次，如两个名词、两个形容词或两个分句。not only 置于句首并强调整个分句时，前半句通常部分倒装，后半句保持常规语序；若它只位于句中修饰两个宾语，则不需要倒装。平行结构提高可读性，但不能代替论证。比较交通时，还应把门到门时间和车上时间区分开，否则句式工整也可能得出误导性结论。</p><p><strong>L44 原创例句：</strong> The night train offers both a quiet place to sleep and a direct route to the city centre.</p><p>夜间列车既提供安静睡眠的地方，又提供直达市中心的路线。</p><p><strong>易错：</strong> both comfortable and saves time 不平行；可改为 both comfortable and convenient，或 It is comfortable and saves time。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">Lesson 44</a></p><h2 id="报告动词及其结构" tabindex="-1">报告动词及其结构 <a class="header-anchor" href="#报告动词及其结构" aria-label="Permalink to &quot;报告动词及其结构 {#报告动词及其结构}&quot;">​</a></h2><p>say 常接内容从句，tell 通常先接人再接内容，claim 表示声称而不必担保真实性，confirm 表示确认某信息。suggest 可接 doing，也可接 that 从句；表示建议时，正式英语可用 should do 或原形虚拟式，不能写 suggest someone to do。不同动词不只是替换 said 的修辞工具，它们会改变信息来源与可信度的呈现。报道时须匹配原说话人的言语行为，避免把推测写成确认，或把建议写成命令。</p><p><strong>L45 原创例句：</strong> The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p><p>记者陈述了数字，而倡议者声称这些数字反映了更广泛的问题。</p><p><strong>易错：</strong> She suggested me to write 错误；可写 She suggested that I write 或 She suggested writing，视执行者是否需要明确。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">Lesson 45</a></p><h2 id="过去能力与一次成功" tabindex="-1">过去能力与一次成功 <a class="header-anchor" href="#过去能力与一次成功" aria-label="Permalink to &quot;过去能力与一次成功 {#过去能力与一次成功}&quot;">​</a></h2><p>could 常表示过去的一般能力，也可用于感知、理解或特定条件下的可能性。描述过去某一次实际克服困难并成功完成，was able to 或 managed to 往往更明确；managed to 还暗含有难度。否定 couldn&#39;t 可以表示一次未能完成，因此不是简单地把 could 禁用于所有单次事件。能力、许可和可能性也可能共用 could，必须结合语境判断。维修叙述中应分别报告尝试与结果，tried to 不保证成功，managed to 则通常表示已实现。</p><p><strong>L46 原创例句：</strong> After several careful attempts, I managed to remove the damaged screw.</p><p>经过几次小心尝试，我终于取出了损坏的螺丝。</p><p><strong>易错：</strong> I tried to fix it 不表示已经修好；若要确认成功，可写 I managed to fix it。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">Lesson 46</a></p><h2 id="because、therefore-与因果关系" tabindex="-1">because、therefore 与因果关系 <a class="header-anchor" href="#because、therefore-与因果关系" aria-label="Permalink to &quot;because、therefore 与因果关系 {#because、therefore-与因果关系}&quot;">​</a></h2><p>because 引导原因从句，能与主句构成一个复合句；therefore 是连接性副词，通常需要句号、分号或与连词配合来连接独立分句，不能仅用一个逗号代替句法连接。because of 后接名词性成分，不能直接接完整分句。语法上的因果标记也需要证据支持，两个现象先后发生不自动构成因果。讨论公共问题时可使用 may contribute to 限定影响，避免把复杂结果归因于单一因素或把个人感受说成普遍事实。</p><p><strong>L47 原创例句：</strong> The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p><p>午夜后庭院仍很嘈杂，因此几位住户把卧室改设在后侧。</p><p><strong>易错：</strong> Because of the traffic was loud 错把完整句接在介词后；可写 Because the traffic was loud 或 Because of the loud traffic。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">Lesson 47</a></p><h2 id="地点前置的完全倒装" tabindex="-1">地点前置的完全倒装 <a class="header-anchor" href="#地点前置的完全倒装" aria-label="Permalink to &quot;地点前置的完全倒装 {#地点前置的完全倒装}&quot;">​</a></h2><p>地点副词或介词短语置前，有时可使用地点加谓语加名词主语的完全倒装，例如 At the end of the road stood a tower，常用于描写场景和引入新信息。谓语一般是不及物的存在、位置或移动动词，不能把任意及物句都这样倒装。若主语是人称代词，通常保持正常语序，如 Here it comes，而不是 Here comes it。主谓一致仍由后置主语决定；这种形式较文学化，连续滥用会让叙述不自然。</p><p><strong>L48 原创例句：</strong> Beyond the empty square stood a row of houses with closed shutters.</p><p>空旷广场的另一边立着一排百叶窗紧闭的房屋。</p><p><strong>易错：</strong> Here comes it 应为 Here it comes；代词主语通常不按名词主语的方式后置。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-048">Lesson 48</a></p><h2 id="介词加关系代词" tabindex="-1">介词加关系代词 <a class="header-anchor" href="#介词加关系代词" aria-label="Permalink to &quot;介词加关系代词 {#介词加关系代词}&quot;">​</a></h2><p>正式表达可将介词放在 whom 或 which 前，如 the person on whom we rely；日常表达常把介词留在从句末尾，如 the person we rely on。介词前置时不能使用 that，也不能省略 whom 或 which。选择哪个介词取决于 rely on、speak to 等实际搭配，而非关系词本身。whose 表所属，不能用来代替所有介词结构。写人物关系时，正式程度不是唯一目标，读者是否能准确识别责任与依赖关系更重要。</p><p><strong>L49 原创例句：</strong> The assistant on whom the household relied kept a careful record of every delivery.</p><p>全家依靠的那位助手仔细记录了每次送货。</p><p><strong>易错：</strong> the person on that we rely 不成立，介词前置需用 whom；或写 the person that we rely on。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-049">Lesson 49</a></p><h2 id="动词后-ing-与-to-do-的意义" tabindex="-1">动词后 ing 与 to do 的意义 <a class="header-anchor" href="#动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;动词后 ing 与 to do 的意义 {#动词后-ing-与-to-do-的意义}&quot;">​</a></h2><p>stop doing 表示停止正在进行或反复进行的动作，stop to do 表示停下原来的事去做另一件事。remember doing 表示记得曾经做过，remember to do 表示记得去执行任务。try doing 强调尝试一种办法，try to do 强调努力完成。两种形式不是可以随意变化的风格选择，实际时间与目的关系会改变。写学习习惯时要先明确是回忆、提醒、停止还是试验方法，再选择结构，避免仅靠中文动词逐字套用。</p><p><strong>L50 原创例句：</strong> I stopped checking messages during study sessions and tried leaving my phone in another room.</p><p>我停止在学习时查看消息，并尝试把手机放到另一间屋里。</p><p><strong>易错：</strong> I stopped to smoke 表示停下其他事去抽烟，不能用来表达戒烟；戒烟应是 stopped smoking。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-050">Lesson 50</a></p>',65)])])}const u=o(r,[["render",s]]);export{g as __pageData,u as default};
